SELECT updated_at
FROM app_application
WHERE tenant_id = #{tenantId}
  AND id = #{applicationId}
  AND deleted_at IS NULL
FOR UPDATE

SELECT COALESCE(MAX(version_no), 0) + 1
FROM app_application_release
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}

mapper.insert:
INSERT INTO app_application_active_release (
    tenant_id, application_id, active_release_id, activated_by, activated_at
) VALUES (
    #{tenantId}, #{applicationId}, #{releaseId}, #{actorId}, #{now}
)
ON CONFLICT (tenant_id, application_id) DO UPDATE
SET active_release_id = EXCLUDED.active_release_id,
    activated_by = EXCLUDED.activated_by,
    activated_at = EXCLUDED.activated_at

mapper.select:
SELECT FROM app_application_release release JOIN app_application_active_release active ON active.tenant_id = release.tenant_id AND active.application_id = release.application_id AND active.active_release_id = release.id WHERE release.tenant_id = #{tenantId} AND release.application_id IN
#{applicationId}
ORDER BY release.application_id

